window.MG_LAZY_DATA["data/lazy/resources/hpc-v27-083-225389fae559022f.json"]={sha256:"225389fae559022f00220daa4af5e4aa7111050458200a3e66d0d8815f7c2c2b",value:{"sources":[{"id":"v27-case-57aeb4947bcc6609","url":"https://materialsproject.github.io/fireworks/dynamic_wf_tutorial.html","title":"FireWorks dynamic workflows","titleEn":"FireWorks dynamic workflows","publisher":"Materials Project / FireWorks","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"hpc-v27-083","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"hpc-v27-083","related":[{"id":"hpc-v27-084","referenceUrls":["https://pegasus.isi.edu/documentation/reference-guide/mapping.html"],"title":"Pegasus：複本目錄、已驗證重用與工作剪枝","titleEn":"Pegasus: replica catalogs, validated reuse and work pruning","why":"用兩課的可觀察驗收條件比較模型邊界：停止理由、迭代數與科學證據完整，才發布最終結果。","whyEn":"Compare model boundaries using observable acceptance criteria: Publish the result only with complete termination reasons, iteration count and scientific evidence.","difference":"使用原創合成資料研究「Pegasus：複本目錄、已驗證重用與工作剪枝」，從物理或資料契約推導計算，並以反例驗證。完成：交付輸出需求清單、重用證明、前後執行集合及工作量帳本。","differenceEn":"Investigate Pegasus: replica catalogs, validated reuse and work pruning using an original synthetic fixture. Derive the calculation from its physical or data contract, challenge it with a counterexample, and defend a bounded conclusion. Complete: Deliver required-output manifests, reuse evidence, before-and-after execution sets and a work ledger distinguishing content validity, catalog location and scheduling consequences.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["列 1、1/2、1/4、1/8、1/16，標初值與四次更新；相等邊界明訂接受。","為 B與D 記錄內容摘要、輸入摘要、參數與驗證狀態；放入同名不同內容檔作負面測例。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["List one, one half, one quarter, one eighth and one sixteenth, separating the initial state from four updates. Declare equality acceptable and identify the first qualifying entry rather than merely the final recorded entry.","Record content digest, input digest, parameters and validation status for B and D. Add a same-name artifact with different bytes as a negative control, distinguishing catalog discovery from scientific qualification.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"hpc-v27-093","referenceUrls":["https://github.com/extra-p/extrap"],"title":"Extra-P：可辨識模型與外推保留樣本","titleEn":"Extra-P: identifiable performance models and held-out extrapolation","why":"用兩課的可觀察驗收條件比較模型邊界：停止理由、迭代數與科學證據完整，才發布最終結果。","whyEn":"Compare model boundaries using observable acceptance criteria: Publish the result only with complete termination reasons, iteration count and scientific evidence.","difference":"使用原創合成資料研究「Extra-P：可辨識模型與外推保留樣本」，從物理或資料契約推導計算，並以反例驗證。完成：交付參數表、三項貢獻圖、保留樣本預測與殘差；記錄擬合、選模、驗證三個資料角色及可外推範圍。","differenceEn":"Investigate Extra-P: identifiable performance models and held-out extrapolation using an original synthetic fixture. Derive the calculation from its physical or data contract, challenge it with a counterexample, and defend a bounded conclusion. Complete: Deliver parameter definitions, term-by-term contributions, frozen held-out predictions and residuals. Distinguish fitting, selection and validation roles, and state the range over which the evidence supports a prediction.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["列 1、1/2、1/4、1/8、1/16，標初值與四次更新；相等邊界明訂接受。","在n=8逐列計算2、4、6秒，再於n=16計算2、8、16秒；將log2的輸入標為無因次，避免對帶秒的量直接取對數。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["List one, one half, one quarter, one eighth and one sixteenth, separating the initial state from four updates. Declare equality acceptable and identify the first qualifying entry rather than merely the final recorded entry.","Build a worksheet showing contributions 2, 4 and 6 seconds at n=8 and 2, 8 and 16 at n=16. Explicitly mark the logarithm argument as dimensionless rather than taking a logarithm of a dimensional duration.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v27-case-2b0f92729c95856e","url":"https://pegasus.isi.edu/documentation/reference-guide/mapping.html","title":"Pegasus workflow mapping","titleEn":"Pegasus workflow mapping","publisher":"USC Information Sciences Institute","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v27-case-df954d6a4cc6b889","url":"https://github.com/extra-p/extrap","title":"Extra-P automated performance modeling","titleEn":"Extra-P automated performance modeling","publisher":"Extra-P project","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
